## C++ Implementation

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n)) return 0;          // no input
    vector<int> A(n);
    for (int i = 0; i < n; ++i) cin >> A[i];

    cin >> m;
    vector<int> B(m);
    for (int i = 0; i < m; ++i) cin >> B[i];

    // 1. Sort both arrays in place
    sort(A.begin(), A.end());
    sort(B.begin(), B.end());

    // 2. Two‑pointer scan
    int i = 0, j = 0;
    bool found = false;
    while (i < n && j < m) {
        if (A[i] == B[j]) {
            if (!found) {                 // first common element
                cout << A[i];
                found = true;
            } else {
                cout << ' ' << A[i];
            }
            ++i; ++j;
        } else if (A[i] < B[j]) {
            ++i;
        } else { // A[i] > B[j]
            ++j;
        }
    }

    if (!found) cout << "No common elements";
    cout << '\n';
    return 0;
}
```

### How to Run

```bash
g++ -std=c++17 -O2 -pipe -static -s -o common common.cpp
./common
```

**Sample Input**

```
