## C++ implementation

```cpp
#include <vector>
#include <stdexcept>

int majorityElement(const std::vector<int>& nums) {
    // 1. Find candidate
    int candidate = 0, count = 0;
    for (int num : nums) {
        if (count == 0) {
            candidate = num;
            count = 1;
        } else if (num == candidate) {
            ++count;
        } else {
            --count;
        }
    }

    // 2. Verify candidate
    int freq = 0;
    for (int num : nums) {
        if (num == candidate) ++freq;
    }
    if (freq > static_cast<int>(nums.size() / 2)) {
        return candidate;
    } else {
        throw std::runtime_error("No majority element found.");
    }
}
```

